Private DesingPattensContext _context ;
public IRepository<Beer> _beers;
public IRepository<Brand> _ brand

IRepository<Beer> Beers
{
get{
return _ beers == null ? _beers = new Repository<beer>(_context):
_beers;
}
IRepository<Brand> Brands
{
get{
return _ brand== null ? _brand = new Repository<Brand>(_context):
_brand;
